static void pixel(uint8_t *f,int x,int y){if(x>=0&&x<200&&y>=0&&y<200)f[y*25+x/8]&=~(0x80>>(x%8));}
static void text(uint8_t *f,int x,int y,const char *s,int scale){for(;*s;s++,x+=6*scale){unsigned char c=*s;if(c>='a'&&c<='z')c-=32;if(c<32||c>90)c='?';for(int col=0;col<5;col++)for(int row=0;row<7;row++)if(font[c-32][col]&(1<<row))for(int dx=0;dx<scale;dx++)for(int dy=0;dy<scale;dy++)pixel(f,x+col*scale+dx,y+row*scale+dy);}}
static uint8_t crc8(const uint8_t *p,int n){uint8_t c=255;while(n--){c^=*p++;for(int i=0;i<8;i++)c=c&128?(c<<1)^0x31:c<<1;}return c;}
static int bcd(int n){return (n>>4)*10+(n&15);}
